---@param arCarObj CSGameObject
---@param pose CS.UnityEngine.Pose
function ARState_CarOperating:OnEnter(aRExhibit)
    log("    ARState_CarOperating:OnEnter   ")
    self.aRExhibit = aRExhibit
    if CommonHelper:GameObjectIsNull(self.aRExhibit) then
        return
    end
    self.aRExhibit.transform:SetParent(nil)
    self.aRCarAnimController = UIUtil.GetTypeChildWightByParent("mesh_shell_beakspider_0",self.aRExhibit, typeof(CS.ARCarAnimController))
    self.aRCarMeshCtrl =UIUtil.GetTypeChildWightByParent("Plane",self.aRExhibit, typeof(CarMeshCtrl))
    CommonHelper:CSGameObjectSetActive(self.aRExhibit,true)
end

function ARState_CarOperating:IsRepeatEnter()
    return false
end

function ARState_CarOperating:OnLeave()
    CommonHelper:CSGameObjectSetActive(self.aRExhibit,false)
    self.arCarObj=nil
    self.aRExhibit=nil
    self.aRCarAnimController=nil
end

