ARSubState_CarOperating_CarMove = class("ARSubState_CarOperating_CarMove")

function ARSubState_CarOperating_CarMove:initialize(stateCtl,subState)
    self.stateCtl = stateCtl
    self.subState = subState
end

function ARSubState_CarOperating_CarMove:OnEnter(pose)
    log("    ARSubState_CarOperating_CarMove:OnEnter   ")
    --self.arCarObj = ARManager:Get().ARCarObj
    if pose then
        self.stateCtl.aRExhibit.transform.localScale = Vector3.one
        self.stateCtl.aRExhibit.transform.position = pose.position
        self.stateCtl.aRExhibit.transform.rotation = pose.rotation
    end
    local lastSubState=ARStateControl:Get().subState
    if lastSubState~= self.subState then
        ARManager:Get():FunctionOpenUpdate(CS.ARFunctionIsOpen.OnClickRayCast,true)
    end
end

function ARSubState_CarOperating_CarMove:IsRepeatEnter()
    return true
end

function ARSubState_CarOperating_CarMove:OnLeave()
    ARManager:Get():FunctionOpenUpdate(CS.ARFunctionIsOpen.OnClickRayCast,false)
end


